import {cashChange} from './bank.js';
import {driving} from './road-vehicles.js';
import {RECIPES,newMeal,heldMeal,mealAlive} from './home-life.js';
import {shiftPay,advanceLife} from './life.js';
export const SERVICE_POINT={x:12,z:13.3},SERVICE_EXIT={x:12,z:20.5};
const yes=message=>({ok:true,message}),no=message=>({ok:false,message});
const near=p=>p&&Math.hypot(p.x-SERVICE_POINT.x,p.z-SERVICE_POINT.z)<1.5;
const unfinished=c=>!['leaving','gone'].includes(c.stage);
export function migrateFoodService(s,data){s.foodService=data?.foodService?structuredClone(data.foodService):{version:1,serial:0,active:false,stock:{rice:0,tomato:0,beans:0,plantain:0},customers:[],order:null,completed:0,earned:0};}
export function validFoodService(f){if(f===undefined)return true;if(!f||f.version!==1||typeof f.active!=='boolean'||!['serial','completed','earned'].every(k=>Number.isSafeInteger(f[k])&&f[k]>=0&&f[k]<=1e9)||!f.stock||!Object.keys(RECIPES.jollof.needs).concat(Object.keys(RECIPES.beans.needs)).every(k=>Number.isInteger(f.stock[k])&&f.stock[k]>=0&&f.stock[k]<=4)||!Array.isArray(f.customers)||f.customers.length>2)return false;const ids=new Set();for(const c of f.customers){if(!c||!Number.isSafeInteger(c.id)||c.id<1||c.id>f.serial||ids.has(c.id)||!Object.hasOwn(RECIPES,c.recipe)||!['scheduled','arriving','queue','leaving','gone'].includes(c.stage)||!['delay','patience','depart'].every(k=>Number.isFinite(c[k])&&c[k]>=0&&c[k]<=120)||!Number.isFinite(c.x)||c.x<11.3||c.x>12.7||!Number.isFinite(c.z)||c.z<13.8||c.z>20.6)return false;ids.add(c.id);}const o=f.order;if(o===null)return true;return !!o&&ids.has(o.id)&&['prepare','cook','ready','carried','served','cancelled'].includes(o.stage)&&Object.hasOwn(RECIPES,o.recipe)&&f.customers.find(c=>c.id===o.id).recipe===o.recipe&&Number.isInteger(o.chops)&&o.chops>=0&&o.chops<=3&&Number.isInteger(o.stirs)&&o.stirs>=0&&o.stirs<=100&&['elapsed','sinceStir'].every(k=>Number.isFinite(o[k])&&o[k]>=0&&o[k]<=100)&&(o.mealId===null||/^cook-[1-9][0-9]*$/.test(o.mealId))&&typeof o.spent==='boolean';}
export function startService(s,view,p,serial){const f=s.foodService;if(driving(s))return no('Park and exit before serving.');if(view!=='city'||!near(p))return no('Approach Mama T’s serving counter.');if(f.active||f.customers.some(c=>c.stage==='leaving')||serial!==f.serial)return no('The current customers are still being handled.');if(heldMeal(s))return no('Store your own carried meal before starting work.');if(s.energy<15)return no('Rest before starting a service shift.');if(f.serial>999999990)return no('Service limit reached.');f.active=true;f.stock={rice:1,tomato:1,beans:1,plantain:1};f.order=null;f.customers=['jollof','beans'].map((recipe,i)=>({id:++f.serial,recipe,stage:'scheduled',delay:i*7,patience:100,depart:0,x:12,z:20.5}));s.job='Serving at Mama T’s';return yes('Two customers are on their way. Mama T provides the ingredients.');}
export const frontCustomer=s=>s.foodService.customers.find(c=>unfinished(c));
function orderAt(s,id,view,p,stages){const f=s.foodService,c=frontCustomer(s),o=f.order;return !driving(s)&&f.active&&view==='city'&&near(p)&&c?.id===id&&c.stage==='queue'&&c.patience>0&&o?.id===id&&stages.includes(o.stage);}
export function acceptServiceOrder(s,id,view,p){const f=s.foodService,c=frontCustomer(s);if(!f.active||view!=='city'||!near(p)||!c||c.id!==id||c.stage!=='queue'||c.patience<=0||f.order&&!['served','cancelled'].includes(f.order.stage))return no('Wait for the next customer at the counter.');if(heldMeal(s))return no('Your hands must be free.');const needs=RECIPES[c.recipe].needs;if(Object.entries(needs).some(([k,n])=>f.stock[k]<n))return no('This shift has no ingredients for that order. Cancel it or leave the shift.');for(const [k,n] of Object.entries(needs))f.stock[k]-=n;f.order={id,recipe:c.recipe,stage:'prepare',chops:0,stirs:0,elapsed:0,sinceStir:2,mealId:null,spent:false};return yes('Order '+id+': '+RECIPES[c.recipe].name+'. Prepare at the counter.');}
export function prepareService(s,id,expected,view,p){if(!orderAt(s,id,view,p,['prepare'])||s.foodService.order.chops!==expected)return no('Preparation already handled or customer unavailable.');const o=s.foodService.order;o.spent=true;o.chops++;if(o.chops===3)o.stage='cook';return yes(o.stage==='cook'?'Prepared. Simmer and stir the pot.':'Prepared '+o.chops+'/3.');}
export function stirService(s,id,expected,view,p){if(!orderAt(s,id,view,p,['cook'])||s.foodService.order.stirs!==expected||s.foodService.order.sinceStir<2)return no('Wait before stirring again.');const o=s.foodService.order;o.stirs=Math.min(100,o.stirs+1);o.sinceStir=0;return yes('Stirred.');}
export function finishServiceCooking(s,id,view,p){if(!orderAt(s,id,view,p,['cook']))return no('Approach the pot with an active order.');const o=s.foodService.order;if(o.elapsed<8||o.stirs<2)return no('Cook eight seconds and stir twice.');o.stage='ready';return yes('Ready. Collect the correct plate, then serve.');}
export function collectServiceMeal(s,id,view,p){if(!orderAt(s,id,view,p,['ready'])||heldMeal(s)||s.daily.cookSerial>=1e9||s.daily.meals.filter(mealAlive).length>=20)return no('Free your hands and meal storage before collecting.');const o=s.foodService.order,mealId='cook-'+(s.daily.cookSerial+1);if(!newMeal(s,mealId,RECIPES[o.recipe].meal,{carry:true}))return no('Plate already collected.');s.daily.cookSerial++;const m=heldMeal(s);m.opened=true;m.serviceOrder=id;o.mealId=mealId;o.stage='carried';return yes('Carrying '+RECIPES[o.recipe].name+' for order '+id+'.');}
export function serveCustomer(s,id,view,p){if(!orderAt(s,id,view,p,['carried']))return no('This customer cannot be served now.');const f=s.foodService,o=f.order,m=heldMeal(s);if(!m||m.id!==o.mealId||m.serviceOrder!==id||m.recipe!==RECIPES[o.recipe].meal)return no('Carry the correct freshly prepared order.');const c=f.customers.find(c=>c.id===id),pay=shiftPay(s,450,true);m.phase='consumed';m.bites=4;m.servedTo=id;c.served=true;c.stage='leaving';c.depart=12;o.stage='served';cashChange(s,pay,'wage',{type:'service',success:true,ref:'service-'+id});f.earned+=pay;f.completed++;s.skills.chef++;s.stats.shifts++;advanceLife(s,10);return yes('Served order '+id+' · earned ₦'+pay+'. Thank you!');}
export function cancelServiceOrder(s,id){const f=s.foodService,c=f.customers.find(c=>c.id===id);if(!c||!unfinished(c))return no('That order is already settled.');const o=f.order;if(o?.id===id&&!['served','cancelled'].includes(o.stage)){if(!o.spent)for(const [k,n] of Object.entries(RECIPES[o.recipe].needs))f.stock[k]+=n;const meal=s.daily.meals.find(m=>m.id===o.mealId);if(meal&&mealAlive(meal))meal.phase='discarded';o.stage='cancelled';}c.stage='leaving';c.depart=12;return yes('Order cancelled. Customer is leaving; no payment.');}
export function leaveService(s){const f=s.foodService;if(!f.active)return no('Shift already closed.');for(const c of f.customers)if(unfinished(c))cancelServiceOrder(s,c.id);f.active=false;s.job='Between shifts';return yes('Shift ended. Completed order payments are saved.');}
export function stepService(s,dt,view,p,{cooking=false}={}){const f=s.foodService,events=[];dt=Math.max(0,Math.min(.05,dt));if(f.active&&(view!=='city'||Math.hypot(p.x-12,p.z-13.3)>10))events.push(leaveService(s).message);if(f.active&&view==='city'){const waiting=f.customers.filter(unfinished);for(const [i,c] of waiting.entries()){if(c.stage==='scheduled'){c.delay=Math.max(0,c.delay-dt);if(!c.delay)c.stage='arriving';}if(c.stage==='arriving'||c.stage==='queue'){const goal=14.9+i*1.35,delta=goal-c.z,nx=c.x+Math.sign(11.6-c.x)*Math.min(Math.abs(11.6-c.x),dt*.9),nz=c.z+Math.sign(delta)*Math.min(Math.abs(delta),dt*.9);if(Math.hypot(nx-p.x,nz-p.z)>.85&&!f.customers.some(other=>other!==c&&!['scheduled','gone'].includes(other.stage)&&Math.hypot(nx-other.x,nz-other.z)<.95)){c.x=nx;c.z=nz;}if(Math.abs(c.z-goal)<.02&&Math.abs(c.x-11.6)<.02)c.stage='queue';else c.stage='arriving';c.patience=Math.max(0,c.patience-dt);if(c.patience===0)events.push(cancelServiceOrder(s,c.id).message);}}const o=f.order;if(cooking&&o?.stage==='cook'&&orderAt(s,o.id,view,p,['cook'])){o.elapsed=Math.min(100,o.elapsed+dt);o.sinceStir=Math.min(100,o.sinceStir+dt);}}
 for(const c of f.customers)if(c.stage==='leaving'){// Step out of the queue before walking back along the separate exit lane.
 const nx=Math.min(12.7,c.x+dt*1.2),nz=c.x<12.68?c.z:Math.min(20.5,c.z+dt*1.2);if(Math.hypot(nx-p.x,nz-p.z)>.85){c.x=nx;c.z=nz;}c.depart=Math.max(0,c.depart-dt);if(c.z>=20.49||c.depart===0){c.stage='gone';events.push('Customer '+c.id+' has left.');}}
 if(f.active&&f.customers.every(c=>c.stage==='gone')){f.active=false;s.job='Between shifts';events.push('Service complete. Both customers have left.');}return events;}
